-- D-Bees of North America: the racial gear its classes print
-- 46 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~116-d-bees-racial-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('walking-stick', 'Walking Stick', 'rifts', 'weapon', NULL, NULL, NULL, '1D8', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A stout walking stick, part of the Adna Nomad''s standard equipment, doing 1D8 S.D.C. as a blunt weapon. No price, weight or length is printed.', 'Rifts World Book 30: D-Bees of North America p.12', NULL),
  ('akysse-vibro-spear', 'Akysse Vibro-Spear', 'rifts', 'weapon', NULL, NULL, NULL, '1D6, 2D4 or 2D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'An improvised Vibro-Spear of the Akysse tribal hunters: one or two Vibro-Knives, or a single Vibro-Saber, fastened to a rod or stick. Printed damage 1D6, 2D4 or 2D6 M.D.; the page does not say which blade gives which figure. No price is printed.', 'Rifts World Book 30: D-Bees of North America p.15', NULL),
  ('akysse-patchwork-hide-armor', 'Akysse Patchwork Hide Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A patchwork suit of Fury Beetle or dinosaur hide worn by Akysse tribal hunters: 4D6+28 M.D.C. M.D.C. IS ROLLED, so the mdc column is empty. No weight, penalty or price is printed.', 'Rifts World Book 30: D-Bees of North America p.15', NULL),
  ('altara-padded-armor', 'Altara Padded M.D.C. Armor and Helmet', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 30, 'The light, padded M.D.C. armor and helmet of the Altara Blind Warrior Women: 30 M.D.C. Apart from her talisman it is the only protection she wears. No weight, penalty or price is printed.', 'Rifts World Book 30: D-Bees of North America p.18', NULL),
  ('crab-warrior-giant-satchel', 'Giant-Sized Satchel (Crab Warrior)', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A giant-sized satchel with a shoulder strap, carried in pairs by Crab Warriors for a few basic items and food; each is large enough to hold a dead body. No price is printed.', 'Rifts World Book 30: D-Bees of North America p.50-51', NULL),
  ('crab-warrior-large-water-skin', 'Large Water Skin, 3-5 gallons (11-19 liters)', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The large water skin of the Crab Warrior, holding 3-5 gallons (11-19 liters). No price is printed.', 'Rifts World Book 30: D-Bees of North America p.51', NULL),
  ('darkhound-piecemeal-body-armor', 'Darkhound Piecemeal Body Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Homemade, piecemeal body armor of the kind a Darkhound puts together: 1D4x10+15 M.D.C. M.D.C. IS ROLLED, so the mdc column is empty. No weight, penalty or price is printed.', 'Rifts World Book 30: D-Bees of North America p.57', NULL),
  ('faerie-bot-environmental-body-armor', 'Faerie Bot Environmental Body Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A tiny suit of environmental body armor sized for the doll-sized Faerie Bot D-Bee: 1D6+22 M.D.C. M.D.C. IS ROLLED, so the mdc column is empty. No weight or price is printed.', 'Rifts World Book 30: D-Bees of North America p.79', NULL),
  ('faerie-bot-portable-radio-and-translator', 'Faerie Bot Portable Radio and Language Translator', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, '10 miles (16 km)', NULL, NULL, NULL, NULL, NULL, 'A tiny portable radio and language translator in one unit, sized for the doll-sized Faerie Bot D-Bee; 10 mile (16 km) range. No price is printed.', 'Rifts World Book 30: D-Bees of North America p.79', NULL),
  ('faerie-bot-protective-helmet', 'Faerie Bot Protective Helmet', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A tiny protective helmet sized for the doll-sized Faerie Bot D-Bee, with a built-in language translator, radio and loudspeaker. The page prints no M.D.C., range or price for it.', 'Rifts World Book 30: D-Bees of North America p.79', NULL),
  ('feni-custom-armor', 'Feni Custom Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 35, 'A custom suit of armor fitted to the Feni Nomad''s unusual anatomy, probably made of M.D.C. animal bone and hide. M.D.C. 35-55 (the low end is stored). Most Feni have one. No weight, penalty or price is printed.', 'Rifts World Book 30: D-Bees of North America p.83', NULL),
  ('carpetbag-large', 'Carpetbag, Large', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The large travelling bag every Fingertooth Carpetbagger starts with, carried over the shoulder with spare clothes, food and whatever is being sold. The book prints no price, weight or capacity.', 'Rifts World Book 30: D-Bees of North America p.86', NULL),
  ('wooden-throwing-knife', 'Wooden Throwing Knife', 'rifts', 'weapon', NULL, NULL, NULL, '1D4 S.D.C.; double damage to vampires', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A throwing knife made of wood, part of a Flooper''s starting kit (1D6+1 of them). The book prints no price, weight or range.', 'Rifts World Book 30: D-Bees of North America p.89', NULL),
  ('silver-plated-throwing-knife', 'Silver-Plated Throwing Knife', 'rifts', 'weapon', NULL, NULL, NULL, '1D6 S.D.C.', 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A silver-plated throwing knife, part of a Flooper''s starting kit (1D6+2 of them). The book prints no price, weight or range, and states no effect against vampires on this line.', 'Rifts World Book 30: D-Bees of North America p.89', NULL),
  ('forest-warden-throwing-stone', 'Forest Warden Throwing Stone', 'rifts', 'weapon', NULL, NULL, NULL, '2D6 S.D.C. restrained throw; 1D4 M.D. full strength throw; 2D4 M.D. power throw (counts as two melee attacks)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A baseball-sized stone; a Forest Warden starts with 2D6+6 of them. The damage is printed for a Forest Warden''s throw. The book prints no price, weight or range.', 'Rifts World Book 30: D-Bees of North America p.93', NULL),
  ('forest-warden-walking-stick-or-club', 'Forest Warden Walking Stick or Club', 'rifts', 'weapon', NULL, NULL, NULL, '2D6 S.D.C. restrained; 1D4 M.D. full strength; 2D4 M.D. power strike (counts as two melee attacks)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A walking stick or club carried by a Forest Warden. The book gives it the same damage as the Forest Warden''s thrown stone, and that damage is stored here; it prints no price or weight.', 'Rifts World Book 30: D-Bees of North America p.93', NULL),
  ('horune-half-suit-body-armor', 'Horune Standard Half Suit Body Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 50, 'The standard half suit of body armor a Horune Pirate starts with. The book prints only its 50 M.D.C.: no price, weight or penalties.', 'Rifts World Book 30: D-Bees of North America p.103', NULL),
  ('mraghiile-patchwork-armor', 'M''Raghiile Makeshift Patchwork Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The makeshift patchwork Mega-Damage armor a M''Raghiile Tree Man starts with. Not environmental. M.D.C. is rolled: 2D6+17; the mdc column holds the lowest roll. No price or weight is printed.', 'Rifts World Book 30: D-Bees of North America p.137', NULL),
  ('nuhr-rune-axe', 'Nuhr Rune Axe', 'rifts', 'weapon', NULL, NULL, NULL, '4D6 M.D.', 1, 'Melee', NULL, NULL, NULL, NULL, NULL, 'One of the notable Nuhr Rune items the Nuhr Dwarves entry lists. A minor rune item: it has no intelligence and no magic powers of its own, and ranks with Techno-Wizard, Eco-Magic or Mystic Kuznya work. The book prints damage only: no price, weight or M.D.C.', 'Rifts World Book 30: D-Bees of North America p.150', NULL),
  ('nuhr-rune-ball-and-chain', 'Nuhr Rune Ball and Chain', 'rifts', 'weapon', NULL, NULL, NULL, '3D6 M.D.', 1, 'Melee', NULL, NULL, NULL, NULL, NULL, 'One of the notable Nuhr Rune items the Nuhr Dwarves entry lists. A minor rune item: it has no intelligence and no magic powers of its own, and ranks with Techno-Wizard, Eco-Magic or Mystic Kuznya work. The book prints damage only: no price, weight or M.D.C.', 'Rifts World Book 30: D-Bees of North America p.150', NULL),
  ('nuhr-rune-morning-star', 'Nuhr Rune Morning Star', 'rifts', 'weapon', NULL, NULL, NULL, '4D6 M.D.', 1, 'Melee', NULL, NULL, NULL, NULL, NULL, 'One of the notable Nuhr Rune items the Nuhr Dwarves entry lists. A minor rune item: it has no intelligence and no magic powers of its own, and ranks with Techno-Wizard, Eco-Magic or Mystic Kuznya work. The book prints damage only: no price, weight or M.D.C.', 'Rifts World Book 30: D-Bees of North America p.150', NULL),
  ('nuhr-rune-hook-with-handle', 'Nuhr Rune Hook with Handle', 'rifts', 'weapon', NULL, NULL, NULL, '1D4 M.D.', 1, 'Melee', NULL, NULL, NULL, NULL, NULL, 'One of the notable Nuhr Rune items the Nuhr Dwarves entry lists. A minor rune item: it has no intelligence and no magic powers of its own, and ranks with Techno-Wizard, Eco-Magic or Mystic Kuznya work. The book prints damage only: no price, weight or M.D.C.', 'Rifts World Book 30: D-Bees of North America p.150', NULL),
  ('nuhr-rune-grappling-hook-and-rope', 'Nuhr Rune Grappling Hook and Rope', 'rifts', 'weapon', NULL, NULL, NULL, '1D4 M.D.', 1, 'Melee', NULL, NULL, NULL, NULL, NULL, 'One of the notable Nuhr Rune items the Nuhr Dwarves entry lists. A minor rune item: it has no intelligence and no magic powers of its own, and ranks with Techno-Wizard, Eco-Magic or Mystic Kuznya work. The length of the rope is not printed. The book prints damage only: no price, weight or M.D.C.', 'Rifts World Book 30: D-Bees of North America p.150', NULL),
  ('nuhr-rune-knife', 'Nuhr Rune Knife', 'rifts', 'weapon', NULL, NULL, NULL, '1D6 M.D.', 1, 'Melee', NULL, NULL, NULL, NULL, NULL, 'One of the notable Nuhr Rune items the Nuhr Dwarves entry lists. A minor rune item: it has no intelligence and no magic powers of its own, and ranks with Techno-Wizard, Eco-Magic or Mystic Kuznya work. The book prints damage only: no price, weight or M.D.C.', 'Rifts World Book 30: D-Bees of North America p.150', NULL),
  ('nuhr-rune-short-sword', 'Nuhr Rune Short Sword, Cutlass or Bayonet', 'rifts', 'weapon', NULL, NULL, NULL, '2D6 M.D.', 1, 'Melee', NULL, NULL, NULL, NULL, NULL, 'One of the notable Nuhr Rune items the Nuhr Dwarves entry lists. A minor rune item: it has no intelligence and no magic powers of its own, and ranks with Techno-Wizard, Eco-Magic or Mystic Kuznya work. One printed entry covers the short sword, the cutlass and the bayonet. The book prints damage only: no price, weight or M.D.C.', 'Rifts World Book 30: D-Bees of North America p.150', NULL),
  ('nuhr-rune-large-sword', 'Nuhr Rune Large Sword', 'rifts', 'weapon', NULL, NULL, NULL, '3D6 M.D.', 1, 'Melee', NULL, NULL, NULL, NULL, NULL, 'One of the notable Nuhr Rune items the Nuhr Dwarves entry lists. A minor rune item: it has no intelligence and no magic powers of its own, and ranks with Techno-Wizard, Eco-Magic or Mystic Kuznya work. The book prints damage only: no price, weight or M.D.C.', 'Rifts World Book 30: D-Bees of North America p.150', NULL),
  ('nuhr-rune-pirate-ship-cannon', 'Nuhr Rune Pirate Ship Cannon (small)', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10+6 M.D.', 1, '3000 feet (914 m)', '20 shots; costs 80 P.P.E. to reload', NULL, NULL, NULL, NULL, 'A small rune-enchanted ship cannon in the gunpowder style of the Nuhr, listed with the ranged Nuhr Rune Weapons. A ship weapon, not personal equipment. No price, weight or M.D.C. is printed.', 'Rifts World Book 30: D-Bees of North America p.150-151', NULL),
  ('nuhr-studded-leather-rune-armor', 'Nuhr Studded Leather Rune Armor', 'rifts', 'armor', 12, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Nuhr Rune Armor, enchanted by engraved runes. M.D.C. is rolled: 4D6+40 M.D.C.; the mdc column holds the lowest roll. Movement penalty printed as -5. One of the two suits the entry names as typical inherited armor. No price is printed.', 'Rifts World Book 30: D-Bees of North America p.151', NULL),
  ('nuhr-leather-and-chain-mail-rune-armor', 'Nuhr Leather and Chain Mail Rune Armor', 'rifts', 'armor', 20, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Nuhr Rune Armor, enchanted by engraved runes. M.D.C. is rolled: 1D4x10+45 (the page omits the unit; the other two suits print M.D.C.); the mdc column holds the lowest roll. -10% movement penalty. No price is printed.', 'Rifts World Book 30: D-Bees of North America p.151', NULL),
  ('nuhr-chain-mail-rune-armor', 'Nuhr Chain Mail Rune Armor', 'rifts', 'armor', 30, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Nuhr Rune Armor, enchanted by engraved runes. M.D.C. is rolled: 1D6x10+90 M.D.C.; the mdc column holds the lowest roll. -20% movement penalty. No price is printed.', 'Rifts World Book 30: D-Bees of North America p.151', NULL),
  ('obsedai-stone-weapon', 'Obsedai Stone Weapon', 'rifts', 'weapon', NULL, NULL, NULL, '6D6 S.D.C. normally; during the Obsedai''s rage it adds 3D6 M.D. to the Obsedai''s punch damage', 0, 'Melee', NULL, NULL, NULL, NULL, 200, 'The stone axe, sword or maul every Obsedai forms from its own body at its coming of age. Supernaturally hard, so it can parry Mega-Damage attacks. It has 200 M.D.C. and is destroyed only if specifically targeted. A destroyed weapon is replaced after 6D6+48 hours of concentration, meditation and fasting, and only one can exist at a time. Not for sale: no price or weight is printed.', 'Rifts World Book 30: D-Bees of North America p.153-154', NULL),
  ('borrowed-ash-pouch', 'Borrowed Ash Pouch', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A small leather pouch holding the mixed ashes of a Septumbran''s ancestors and dead relatives; every Septumbran starts with one. While it is kept safe on the owner''s person: +2 to save vs magic, poison and disease, and +10% to save vs Coma/Death. It works only for the Septumbran who filled it from the family''s communal urn, never for anyone else, and extra pouches do not stack. No price is printed.', 'Rifts World Book 30: D-Bees of North America p.179', NULL),
  ('septumbran-patchwork-armor', 'Septumbran Patchwork Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Patchwork M.D.C. body armor as worn by Septumbran Witch Wolves: 3D6+28 M.D.C. (roll once for the suit). Printed on the race''s M.D.C. line, which otherwise says by armor or magic; the book gives no weight, penalties or price.', 'Rifts World Book 30: D-Bees of North America p.178', NULL),
  ('shale-bogle-patchwork-armor', 'Shale Bogle Patchwork Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The suit of patchwork M.D.C. armor a Shale Bogle hunter/defender or adventurer starts with: 4D6+28 M.D.C. (roll once for the suit). The book gives no weight, penalties or price.', 'Rifts World Book 30: D-Bees of North America p.182', NULL),
  ('shaper-light-partial-armor', 'Shaper Light Partial Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The set of light, partial M.D.C. armor among a Shaper''s typical possessions: 2D6+20 M.D.C. (roll once for the suit). The book gives no weight, penalties or price.', 'Rifts World Book 30: D-Bees of North America p.184', NULL),
  ('shemarrian-rail-gun', 'Shemarrian Rail Gun', 'rifts', 'weapon', 128, NULL, 'Black Market: not available; none have reached it.', '2D6x10 M.D. per round', 1, '6000 feet (1828 m)', '12 in the gun; reloaded by hand at 1D4+3 rounds per melee round (15 seconds), or belt fed from an ammo drum of 820 rounds (drum 390 lbs/175 kg)', 'Each single round fired counts as one melee attack', NULL, NULL, 70, 'The Shemarrian Warrior''s electromagnetic mass driver, on the principle of the Glitter Boy''s Boom Gun but built for accuracy, with a suppressor that cuts the recoil and the boom to about a shotgun''s report. Each cartridge bursts into hundreds of flechettes. Primary purpose: assault and anti-armor. Gun 128 lbs (57.6 kg); belt 30 lbs (13.5 kg). Built-in sensors, computer-guided sight and laser targeting: +2 to strike with this weapon. The gun''s own 70 M.D.C. is from the Improved Shemarrian''s M.D.C. by Location on printed 186, where it is a small target needing a Called Shot at -3. It is linked to its owner: it explodes when she is destroyed, or when anyone but a Shemarrian, Archie, Hagan or an Archie ''Bot tampers with it, doing 5D6 M.D. to everyone within 5 feet (1.5 m).', 'Rifts World Book 30: D-Bees of North America p.187', NULL),
  ('spinne-light-force-field', 'Spinne Light Force Field', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, 'Small rechargeable energy cell, or adapted to run on E-Clips', NULL, NULL, NULL, 40, 'The lightest of the four Spinne personal force fields, used for ceremonial occasions and for personal protection in dangerous work. Spinne can hardly wear armor, so the generator is built into a belt or web-gear, plain or ornate. The book prints no duration, weight or price.', 'Rifts World Book 30: D-Bees of North America p.197', NULL),
  ('spinne-medium-force-field', 'Spinne Medium Force Field', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, 'Small rechargeable energy cell, or adapted to run on E-Clips', NULL, NULL, NULL, 80, 'A Spinne personal force field built into a belt or web-gear; the strength scouts and spies favor and the one most often assigned to support forces and pilots. Power is printed with the Light field on printed 197. The book prints no duration, weight or price.', 'Rifts World Book 30: D-Bees of North America p.198', NULL),
  ('spinne-heavy-force-field', 'Spinne Heavy Force Field', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, 'Small rechargeable energy cell, or adapted to run on E-Clips', NULL, NULL, NULL, 160, 'A Spinne personal force field built into a belt or web-gear; the strength assigned to front-line infantry. Power is printed with the Light field on printed 197. The book prints no duration, weight or price.', 'Rifts World Book 30: D-Bees of North America p.198', NULL),
  ('spinne-super-heavy-force-field', 'Spinne Super-Heavy Force Field', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, 'Small rechargeable energy cell, or adapted to run on E-Clips', NULL, NULL, NULL, 250, 'The strongest Spinne personal force field, built into a belt or web-gear and reserved for heavy assault troops. Power is printed with the Light field on printed 197. The book prints no duration, weight or price.', 'Rifts World Book 30: D-Bees of North America p.198', NULL);

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('swamp-sludger-partial-armor', 'Swamp Sludger Partial Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The partial M.D.C. body armor a Swamp Sludger starts with: 4D6+28 M.D.C. (roll once for the suit). Most Sludgers wear little clothing or armor beyond it. The book gives no weight, penalties or price.', 'Rifts World Book 30: D-Bees of North America p.201', NULL),
  ('vernulian-force-field-collar-military', 'Vernulian Force Field Collar (Military)', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 160, 'The energy field generator collar of the Vernulian military; soldiers have one. It raises an invisible force field of 160 M.D.C. that regenerates lost M.D.C. at 10 points per hour. Use is limited to 12 hours a day, or the system overloads and shuts down for 24 hours, so it is switched on only when needed. It also keeps the wearer warm (metabolism at combat peak) in cool periods such as desert nights. Custom-made M.D.C. body armor may be worn as well. No price is printed.', 'Rifts World Book 30: D-Bees of North America p.211-212', NULL),
  ('vernulian-force-field-collar-commercial', 'Vernulian Force Field Collar (Commercial)', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 100, 'The commercial-work version of the Vernulian energy field generator collar; only 30% of Vernulian refugees have one. It raises an invisible force field of 100 M.D.C. that regenerates lost M.D.C. at 10 points per hour. Use is limited to 12 hours a day, or the system overloads and shuts down for 24 hours. It also keeps the wearer warm in cool periods such as desert nights. No price is printed.', 'Rifts World Book 30: D-Bees of North America p.211-212', NULL),
  ('vintex-medium-armor', 'Vintex Medium Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The suit of medium or non-environmental M.D.C. armor a Vintex Warrior starts with: 4D6+40 M.D.C. (roll once for the suit). The tail is usually left unarmored. The book gives no weight, penalties or price.', 'Rifts World Book 30: D-Bees of North America p.215', NULL),
  ('yhabbayar-bubble-solution-waterskin', 'Waterskin of Bubble Solution (Yhabbayar)', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A waterskin filled with the plain soap-and-water solution a Yhabbayar blows bubbles from. The race needs these simple physical components to make its bubbles. The book prints no capacity, number of uses or price.', 'Rifts World Book 30: D-Bees of North America p.220', NULL),
  ('yhabbayar-bubble-ring', 'Bubble-Blowing Ring (Yhabbayar)', 'rifts', 'gear', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A ring or hoop a Yhabbayar blows bubbles through; a starting character carries 1D6 of them. The race needs these simple physical components to make its bubbles. The book prints no size, material or price.', 'Rifts World Book 30: D-Bees of North America p.220', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'gear rows, part 1: 40 are in' AS assertion, count(*) AS got, 40 AS want
  FROM gear WHERE slug IN ('walking-stick', 'akysse-vibro-spear', 'akysse-patchwork-hide-armor', 'altara-padded-armor', 'crab-warrior-giant-satchel', 'crab-warrior-large-water-skin', 'darkhound-piecemeal-body-armor', 'faerie-bot-environmental-body-armor', 'faerie-bot-portable-radio-and-translator', 'faerie-bot-protective-helmet', 'feni-custom-armor', 'carpetbag-large', 'wooden-throwing-knife', 'silver-plated-throwing-knife', 'forest-warden-throwing-stone', 'forest-warden-walking-stick-or-club', 'horune-half-suit-body-armor', 'mraghiile-patchwork-armor', 'nuhr-rune-axe', 'nuhr-rune-ball-and-chain', 'nuhr-rune-morning-star', 'nuhr-rune-hook-with-handle', 'nuhr-rune-grappling-hook-and-rope', 'nuhr-rune-knife', 'nuhr-rune-short-sword', 'nuhr-rune-large-sword', 'nuhr-rune-pirate-ship-cannon', 'nuhr-studded-leather-rune-armor', 'nuhr-leather-and-chain-mail-rune-armor', 'nuhr-chain-mail-rune-armor', 'obsedai-stone-weapon', 'borrowed-ash-pouch', 'septumbran-patchwork-armor', 'shale-bogle-patchwork-armor', 'shaper-light-partial-armor', 'shemarrian-rail-gun', 'spinne-light-force-field', 'spinne-medium-force-field', 'spinne-heavy-force-field', 'spinne-super-heavy-force-field') AND source_book IS NOT NULL;
SELECT 'gear rows, part 2: 6 are in' AS assertion, count(*) AS got, 6 AS want
  FROM gear WHERE slug IN ('swamp-sludger-partial-armor', 'vernulian-force-field-collar-military', 'vernulian-force-field-collar-commercial', 'vintex-medium-armor', 'yhabbayar-bubble-solution-waterskin', 'yhabbayar-bubble-ring') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~116-d-bees-racial-gear.sql');
